-- User-provided 100-supplier GPU quote workbook. Quotes, availability, SLA and identities remain unverified.

CREATE TABLE supplier_quote_directory_sources (
  source_id text PRIMARY KEY CHECK (source_id='gpu-supplier-workbook-2026-08-17'),
  source_file_name text NOT NULL,
  source_sha256 text NOT NULL CHECK (source_sha256 ~ '^sha256:[a-f0-9]{64}$'),
  source_kind text NOT NULL CHECK (source_kind='USER_PROVIDED_SUPPLIER_WORKBOOK'),
  source_observed_at date NOT NULL,
  valid_until timestamptz NOT NULL,
  verification_status text NOT NULL CHECK (verification_status='unverified'),
  supplier_count integer NOT NULL CHECK (supplier_count=100),
  publication_directive_ref text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (valid_until > source_observed_at::timestamptz)
);

CREATE TABLE supplier_quote_directory_items (
  id uuid PRIMARY KEY,
  source_id text NOT NULL REFERENCES supplier_quote_directory_sources(source_id),
  source_row integer NOT NULL UNIQUE CHECK (source_row BETWEEN 1 AND 100),
  supplier_id text NOT NULL UNIQUE CHECK (supplier_id ~ '^supplier-quote-20260817-[0-9]{3}$'),
  legal_name text NOT NULL CHECK (char_length(legal_name) BETWEEN 2 AND 160),
  display_name text NOT NULL CHECK (char_length(display_name) BETWEEN 2 AND 160),
  entity_type text,
  locations jsonb NOT NULL CHECK (jsonb_typeof(locations)='array'),
  declared_gpu_description text NOT NULL,
  declared_gpu_models jsonb NOT NULL CHECK (jsonb_typeof(declared_gpu_models)='array'),
  quotes jsonb NOT NULL CHECK (jsonb_typeof(quotes)='array' AND jsonb_array_length(quotes)>0),
  contract_terms text,
  network_description text,
  source_availability_claim text,
  source_sla_claim text,
  source_notes text,
  logo_https_url text CHECK (logo_https_url IS NULL OR logo_https_url ~ '^https://'),
  logo_source_url text CHECK (logo_source_url IS NULL OR logo_source_url ~ '^https://'),
  logo_status text NOT NULL CHECK (logo_status IN ('official_domain_candidate','not_verified')),
  availability_status text NOT NULL DEFAULT 'inquiry_required' CHECK (availability_status='inquiry_required'),
  inventory_commitment boolean NOT NULL DEFAULT false CHECK (inventory_commitment=false),
  purchasable boolean NOT NULL DEFAULT false CHECK (purchasable=false),
  order_creation boolean NOT NULL DEFAULT false CHECK (order_creation=false),
  inquiry_available boolean NOT NULL DEFAULT true CHECK (inquiry_available=true),
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX supplier_quote_directory_search ON supplier_quote_directory_items(source_row,legal_name);

VALUES('gpu-supplier-workbook-2026-08-17','GPU算力租赁报价单_100家供应商.xlsx','sha256:6830d0d10000b9d87424dc33d662b6b27a1a10f47b76455ce555806088874b41','USER_PROVIDED_SUPPLIER_WORKBOOK','2026-08-17','2026-09-17T15:59:59.000Z','unverified',100,'platform-directive:2026-08-23:import-all-100-supplier-quotes')
ON CONFLICT(source_id) DO NOTHING;

ON CONFLICT(source_row) DO NOTHING;

DO $$
DECLARE item_count integer;
DECLARE invalid_count integer;
BEGIN
  SELECT count(*) INTO item_count FROM supplier_quote_directory_items WHERE source_id='gpu-supplier-workbook-2026-08-17' AND active;
  SELECT count(*) INTO invalid_count FROM supplier_quote_directory_items WHERE source_id='gpu-supplier-workbook-2026-08-17' AND (purchasable OR order_creation OR inventory_commitment OR NOT inquiry_available OR availability_status<>'inquiry_required');
  IF item_count<>100 THEN RAISE EXCEPTION 'supplier quote directory must contain exactly 100 active rows'; END IF;
  IF invalid_count<>0 THEN RAISE EXCEPTION 'supplier quote directory cannot claim inventory or purchase capability'; END IF;
END $$;
